/* Minimal stub for the Zephyr BSD-style sockets API.
 *
 * The T16 skeleton includes <zephyr/net/socket.h> but does not yet call
 * any socket APIs — the publish loop is deferred to T17+. This header
 * therefore declares no symbols. It exists so the C syntax gate does
 * not fail on a missing include.
 */
#ifndef DEMOL_STUB_ZEPHYR_NET_SOCKET_H
#define DEMOL_STUB_ZEPHYR_NET_SOCKET_H

#endif /* DEMOL_STUB_ZEPHYR_NET_SOCKET_H */
